module DIG_BitExtenderSingle #(
    parameter outputBits = 2
)
(
    input in,
    output [(outputBits - 1):0] out
);
    assign out = {outputBits{in}};
endmodule



module DIG_RAMDualAccess
#(
    parameter Bits = 8,
    parameter AddrBits = 4
)
(
    input C, // Clock signal
    input ld,
    input [(AddrBits-1):0] \1A ,
    input [(AddrBits-1):0] \2A ,
    input [(Bits-1):0] \1Din ,
    input str,
    output [(Bits-1):0] \1D ,
    output [(Bits-1):0] \2D
);
    // CAUTION: uses distributed RAM
    reg [(Bits-1):0] memory [0:((1 << AddrBits)-1)];

    assign \1D = ld? memory[\1A ] : 'hz;
    assign \2D = memory[\2A ];

    always @ (posedge C) begin
        if (str)
            memory[\1A ] <= \1Din ;
    end

endmodule



module RAM_256KB (
  input [15:0] INSAddressIn,
  input [3:0] ByteSelect,
  input [15:0] AddressIn,
  input [31:0] Din,
  input We,
  input Clock,
  output [31:0] Dout,
  output [31:0] INSout
);
  wire [3:0] s0;
  wire s1;
  wire s2;
  wire s3;
  wire s4;
  wire [7:0] s5;
  wire [7:0] s6;
  wire [7:0] s7;
  wire [7:0] s8;
  wire [3:0] s9;
  wire [7:0] s10;
  wire [7:0] s11;
  wire [7:0] s12;
  wire [7:0] s13;
  wire [7:0] s14;
  wire [7:0] s15;
  wire [7:0] s16;
  wire [7:0] s17;
  DIG_BitExtenderSingle #(
    .outputBits(4)
  )
  DIG_BitExtenderSingle_i0 (
    .in( We ),
    .out( s9 )
  );
  assign s5 = Din[7:0];
  assign s6 = Din[15:8];
  assign s7 = Din[23:16];
  assign s8 = Din[31:24];
  assign s0 = (s9 & ByteSelect);
  assign s1 = s0[0];
  assign s2 = s0[1];
  assign s3 = s0[2];
  assign s4 = s0[3];
  // Byte 2
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i1 (
    .str( s3 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s7 ),
    .\2A ( INSAddressIn ),
    .\1D ( s12 ),
    .\2D ( s14 )
  );
  // Byte 3
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i2 (
    .str( s4 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s8 ),
    .\2A ( INSAddressIn ),
    .\1D ( s13 ),
    .\2D ( s15 )
  );
  // Byte 0
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i3 (
    .str( s1 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s5 ),
    .\2A ( INSAddressIn ),
    .\1D ( s10 ),
    .\2D ( s16 )
  );
  // Byte 1
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i4 (
    .str( s2 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s6 ),
    .\2A ( INSAddressIn ),
    .\1D ( s11 ),
    .\2D ( s17 )
  );
  assign Dout[7:0] = s10;
  assign Dout[15:8] = s11;
  assign Dout[23:16] = s12;
  assign Dout[31:24] = s13;
  assign INSout[7:0] = s16;
  assign INSout[15:8] = s17;
  assign INSout[23:16] = s14;
  assign INSout[31:24] = s15;
endmodule

module Mux_2x1_NBits #(
    parameter Bits = 2
)
(
    input [0:0] sel,
    input [(Bits - 1):0] in_0,
    input [(Bits - 1):0] in_1,
    output reg [(Bits - 1):0] out
);
    always @ (*) begin
        case (sel)
            1'h0: out = in_0;
            1'h1: out = in_1;
            default:
                out = 'h0;
        endcase
    end
endmodule


module MemoryMapperExp (
  input Clock,
  input [31:0] Din,
  input [31:0] Ain,
  input [31:0] INSAin,
  input [3:0] ByteSelect,
  input We,
  input [2:0] RegInsel,
  input [31:0] DrIO,
  output [31:0] INSout,
  output [31:0] Dout,
  output [31:0] AddIO,
  output [31:0] DwIO,
  output WeIO,
  output ReIO,
  output CLKIO
);
  wire [15:0] s0;
  wire [15:0] s1;
  wire s2;
  wire [31:0] s3;
  wire [31:0] s4;
  wire s5;
  wire [10:0] s6;
  wire [31:0] s7;
  wire [31:0] s8;
  wire s9;
  wire [31:0] s10;
  wire [2:0] s11;
  wire s12;
  wire [2:0] s13;
  wire s14;
  wire [10:0] s15;
  AddressSpace AddressSpace_i0 (
    .Ain( Ain ),
    .Enable( s11 )
  );
  AddressSpace AddressSpace_i1 (
    .Ain( INSAin ),
    .Enable( s13 )
  );
  Decoder3 Decoder3_i2 (
    .sel( RegInsel ),
    .out_1( s14 )
  );
  assign s1 = Ain[17:2];
  assign s0 = INSAin[17:2];
  assign s6 = Ain[12:2];
  assign s15 = INSAin[12:2];
  // INSROM
  DIG_ROM_2048X32_INSROM DIG_ROM_2048X32_INSROM_i3 (
    .A( s15 ),
    .sel( 1'b1 ),
    .D( s10 )
  );
  // RROM
  DIG_ROM_2048X32_RROM DIG_ROM_2048X32_RROM_i4 (
    .A( s6 ),
    .sel( 1'b1 ),
    .D( s7 )
  );
  assign s5 = s11[1];
  assign s12 = s11[2];
  assign s9 = s13[1];
  assign s2 = (We & s5);
  assign WeIO = (We & s12);
  assign ReIO = (s12 & s14);
  RAM_256KB RAM_256KB_i5 (
    .INSAddressIn( s0 ),
    .ByteSelect( ByteSelect ),
    .AddressIn( s1 ),
    .Din( Din ),
    .We( s2 ),
    .Clock( Clock ),
    .Dout( s3 ),
    .INSout( s4 )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i6 (
    .sel( s5 ),
    .in_0( s7 ),
    .in_1( s3 ),
    .out( s8 )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i7 (
    .sel( s9 ),
    .in_0( s10 ),
    .in_1( s4 ),
    .out( INSout )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i8 (
    .sel( s12 ),
    .in_0( s8 ),
    .in_1( DrIO ),
    .out( Dout )
  );
  assign AddIO = Ain;
  assign DwIO = Din;
  assign CLKIO = Clock;
endmodule
module DIG_BitExtender #(
    parameter inputBits = 2,
    parameter outputBits = 4
)
(
    input [(inputBits-1):0] in,
    output [(outputBits - 1):0] out
);
    assign out = {{(outputBits - inputBits){in[inputBits - 1]}}, in};
endmodule




module Decoder2 (
    output out_0,
    output out_1,
    output out_2,
    output out_3,
    input [1:0] sel
);
    assign out_0 = (sel == 2'h0)? 1'b1 : 1'b0;
    assign out_1 = (sel == 2'h1)? 1'b1 : 1'b0;
    assign out_2 = (sel == 2'h2)? 1'b1 : 1'b0;
    assign out_3 = (sel == 2'h3)? 1'b1 : 1'b0;
endmodule


module Mux_16x1_NBits #(
    parameter Bits = 2
)
(
    input [3:0] sel,
    input [(Bits - 1):0] in_0,
    input [(Bits - 1):0] in_1,
    input [(Bits - 1):0] in_2,
    input [(Bits - 1):0] in_3,
    input [(Bits - 1):0] in_4,
    input [(Bits - 1):0] in_5,
    input [(Bits - 1):0] in_6,
    input [(Bits - 1):0] in_7,
