  wire [31:0] s23;
  wire s24;
  wire [3:0] s25;
  wire s26;
  wire s27;
  wire s28;
  wire s29;
  assign s24 = (half | isbyte);
  assign s0 = AddressIn[1:0];
  assign s1 = DinMMU[7:0];
  assign s2 = DinMMU[15:8];
  assign s3 = DinMMU[23:16];
  assign s4 = DinMMU[31:24];
  assign s5[7:0] = s1;
  assign s5[15:8] = s2;
  assign s6[7:0] = s2;
