  assign s7[15:8] = s4;
  DIG_BitExtender #(
    .inputBits(8),
    .outputBits(32)
  )
  DIG_BitExtender_i0 (
    .in( s1 ),
    .out( s8 )
  );
  assign s9[7:0] = s1;
  assign s9[31:8] = 24'b0;
  DIG_BitExtender #(
    .inputBits(8),
    .outputBits(32)
  )
  DIG_BitExtender_i1 (
    .in( s2 ),
    .out( s12 )
  );
  assign s13[7:0] = s2;
  assign s13[31:8] = 24'b0;
  DIG_BitExtender #(
    .inputBits(8),
    .outputBits(32)
  )
  DIG_BitExtender_i2 (
    .in( s3 ),
    .out( s16 )
  );
  assign s17[7:0] = s3;
  assign s17[31:8] = 24'b0;
  DIG_BitExtender #(
    .inputBits(8),
    .outputBits(32)
  )
  DIG_BitExtender_i3 (
    .in( s4 ),
    .out( s20 )
  );
  assign s21[7:0] = s4;
  assign s21[31:8] = 24'b0;
  assign s22[0] = ~ \Signed ;
  assign s22[1] = ~ isbyte;
  assign s22[3:2] = s0;
  Decoder2 Decoder2_i4 (
    .sel( s0 ),
    .out_0( s26 ),
    .out_1( s27 ),
    .out_2( s28 ),
    .out_3( s29 )
  );
  DIG_BitExtender #(
    .inputBits(16),
    .outputBits(32)
  )
  DIG_BitExtender_i5 (
    .in( s5 ),
    .out( s10 )
  );
  assign s11[15:0] = s5;
  assign s11[31:16] = 16'b0;
  DIG_BitExtender #(
    .inputBits(16),
    .outputBits(32)
  )
  DIG_BitExtender_i6 (
    .in( s6 ),
    .out( s14 )
  );
  assign s15[15:0] = s6;
  assign s15[31:16] = 16'b0;
  DIG_BitExtender #(
    .inputBits(16),
    .outputBits(32)
  )
  DIG_BitExtender_i7 (
    .in( s7 ),
    .out( s18 )
  );
  assign s19[15:0] = s7;
  assign s19[31:16] = 16'b0;
  assign s25[0] = s26;
  assign s25[1] = ((s26 & half) | s27);
  assign s25[2] = ((s27 & half) | s28);
  assign s25[3] = ((s28 & half) | s29);
  Mux_16x1_NBits #(
    .Bits(32)
  )
  Mux_16x1_NBits_i8 (
    .sel( s22 ),
    .in_0( s8 ),
    .in_1( s9 ),
    .in_2( s10 ),
    .in_3( s11 ),
    .in_4( s12 ),
    .in_5( s13 ),
