  assign s4 = ~ B;
  Decoder4 Decoder4_i0 (
    .sel( OPSELECT ),
    .out_1( s8 ),
    .out_5( s9 ),
    .out_6( s10 )
  );
  assign s17 = (~ OPSELECT[3] & OPSELECT[2] & OPSELECT[1] & ~ OPSELECT[0]);
  assign s1 = (s8 | s9 | s10);
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i1 (
    .sel( s1 ),
    .in_0( B ),
    .in_1( s4 ),
    .out( s0 )
  );
  // Adder
  DIG_Add #(
    .Bits(32)
  )
  DIG_Add_i2 (
    .a( A ),
    .b( s0 ),
    .c_i( s1 ),
    .s( s2 ),
    .c_o( s3 )
  );
  assign s5 = (A & s0);
  assign s6 = (A | s0);
  assign s7 = (A ^ s0);
  assign s16 = s0[4:0];
  assign s11[0] = ~ s3;
  assign s11[31:1] = 31'b0;
  assign s12[0] = (((~ A[31] & B[31] & s2[31]) | (A[31] & ~ B[31] & ~ s2[31])) ^ s2[31]);
  assign s12[31:1] = 31'b0;
  SLL SLL_i3 (
    .in( A ),
    .shift( s16 ),
    .out( s13 )
  );
  SRL SRL_i4 (
    .in( A ),
    .shift( s16 ),
    .out( s14 )
  );
  SRA SRA_i5 (
    .in( A ),
    .shift( s16 ),
    .out( s15 )
